import time as time_module
from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

import pytest
from DateTime import DateTime
from babel.dates import format_date

import zms.unibe.helpers.datetime as datetime_helpers


ZURICH = ZoneInfo('Europe/Zurich')
UTC = timezone.utc
SAMPLE = datetime(2024, 3, 31, 0, 30, tzinfo=UTC)


@pytest.mark.parametrize(
    'value',
    [
        pytest.param(datetime(2024, 1, 15, 12), id='naive-datetime'),
        pytest.param(datetime(2024, 1, 15, 12, tzinfo=UTC), id='aware-datetime'),
        pytest.param('2024-01-15T12:00:00', id='naive-iso-string'),
        pytest.param('2024-01-15T12:00:00+00:00', id='aware-iso-string'),
        pytest.param(date(2024, 1, 15), id='date'),
        pytest.param(time(12, 30), id='time'),
        pytest.param(time_module.struct_time((2024, 1, 15, 12, 30, 0, 0, 15, -1)), id='struct-time'),
        pytest.param(DateTime('2024-01-15T12:00:00+00:00'), id='zope-datetime'),
    ],
)
def test_local_timezone_converts_supported_datetime_inputs(value):
    converted = datetime_helpers.local_timezone(value, tz='UTC')

    if isinstance(value, time_module.struct_time):
        expected = datetime.fromtimestamp(time_module.mktime(value), UTC)
    elif isinstance(value, DateTime):
        expected = datetime.fromisoformat(value.ISO8601()).astimezone(UTC)
    elif isinstance(value, date) and not isinstance(value, datetime):
        expected = datetime.combine(value, time.min, tzinfo=UTC)
    elif isinstance(value, time):
        expected = datetime.combine(datetime.now(UTC).date(), value, tzinfo=UTC)
    elif isinstance(value, datetime) and value.tzinfo is None:
        expected = value.replace(tzinfo=UTC)
    elif isinstance(value, str):
        parsed = datetime.fromisoformat(value)
        expected = parsed.replace(tzinfo=UTC) if parsed.tzinfo is None else parsed.astimezone(UTC)
    else:
        expected = value.astimezone(UTC)

    assert converted == expected


@pytest.mark.parametrize('timestamp', [0, 1_710_000_000.5], ids=['integer', 'float'])
def test_local_timezone_converts_unix_timestamps(timestamp):
    converted = datetime_helpers.local_timezone(timestamp, tz='UTC')

    assert converted == datetime.fromtimestamp(timestamp, UTC)


def test_local_timezone_preserves_offset_from_iso_string_by_default():
    converted = datetime_helpers.local_timezone('2024-01-15T12:00:00+05:00')

    assert converted.utcoffset() == timedelta(hours=5)
    assert converted.hour == 12


def test_local_timezone_assigns_default_timezone_to_naive_calendar_values():
    converted = datetime_helpers.local_timezone(date(2024, 1, 15))

    assert converted.date() == date(2024, 1, 15)
    assert converted.tzinfo.key == 'Europe/Zurich'


def test_local_timezone_uses_default_timezone_for_missing_or_unknown_timezone():
    source = datetime(2024, 1, 15, 12, tzinfo=UTC)

    assert datetime_helpers.local_timezone(source).tzinfo.key == 'Europe/Zurich'
    assert datetime_helpers.local_timezone(source, tz='Unknown/Timezone').tzinfo.key == 'Europe/Zurich'


def test_local_timezone_accepts_timezone_objects_and_applies_day_delta():
    source = datetime(2024, 1, 15, 12, tzinfo=UTC)

    converted = datetime_helpers.local_timezone(source, tz=ZURICH, days_delta=2)

    assert converted == datetime(2024, 1, 17, 13, tzinfo=ZURICH)


def test_local_timezone_uses_zoneinfo_daylight_saving_rules():
    converted = datetime_helpers.local_timezone(
        datetime(2024, 3, 31, 0, 30, tzinfo=UTC),
        tz='Europe/Zurich',
    )

    assert converted == datetime(2024, 3, 31, 1, 30, tzinfo=ZURICH)
    assert converted.utcoffset() == timedelta(hours=1)


