def test_local_timezone_uses_current_time_when_input_is_none(monkeypatch):
    frozen_now = datetime(2024, 1, 15, 12)

    class FrozenDateTime(datetime):
        @classmethod
        def now(cls, tz=None):
            return frozen_now.replace(tzinfo=tz)

    monkeypatch.setattr(datetime_helpers, 'datetime', FrozenDateTime)

    assert datetime_helpers.local_timezone(tz='UTC') == frozen_now.replace(tzinfo=UTC)


